using System.Text;

namespace DwarfMapper.Generator.Tests.SelfValidation
{
    /// <summary>
    ///     <b>A mutation leg compiles only what it mutates</b> (round 34): <c>Set-UnmutatedSourcesGenerated</c> in
    ///     <c>scripts/gate-checks.ps1</c> gives every source the leg's <c>mutate</c> globs do not name an
    ///     <c>&lt;auto-generated&gt;</c> header, which Stryker 4.16 compiles without mutating. On the generator leg that
    ///     took mutate-and-compile from 2:20 to 0:17 on four CPUs with the same mutants tested, so what it must never do
    ///     is touch a source a glob names, pass on a glob that names nothing, or run on a working tree.
    ///     <para>
    ///         Driven through <c>pwsh</c> against the REAL function and a fake repository in a temp directory
    ///         (<see cref="PwshBattery" />, ARCH-06: registered in <see cref="RepoWriteGuardTests" />).
    ///     </para>
    /// </summary>
    public class UnmutatedSourcesMarkingTests
    {
        private const string Spdx = "// SPDX-License-Identifier: GPL-2.0-only";

        private const string Marker =
            "// <auto-generated/> outside this mutation leg's globs, so Stryker compiles it without mutating it (Set-UnmutatedSourcesGenerated)";

        [Fact]
        public void Only_sources_no_glob_names_are_marked_and_nothing_else_changes()
        {
            var dir = Path.Combine(Path.GetTempPath(), "dwarfmapper-unmutated-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(dir);
            try
            {
                var project = Path.Combine(dir, "src", "Proj");
                WriteTemp(Path.Combine(project, "Proj.csproj"),
                    "<Project Sdk=\"Microsoft.NET.Sdk\"><ItemGroup><Compile Include=\"..\\Shared\\Linked.cs\" Link=\"Shared\\Linked.cs\"/></ItemGroup></Project>",
                    false);
                WriteTemp(Path.Combine(project, "Core", "InScope.cs"), Spdx + "\nnamespace P { class InScope { } }\n", false);
                WriteTemp(Path.Combine(project, "Core", "OutOfScope.cs"), Spdx + "\r\nnamespace P { class OutOfScope { } }\r\n", false);
                WriteTemp(Path.Combine(project, "Core", "NoHeader.cs"), "namespace P { class NoHeader { } }\n", false);
                WriteTemp(Path.Combine(project, "Diagnostics", "Descriptors.cs"),
                    Spdx + "\nnamespace P { static class D { public static readonly DiagnosticDescriptor X = new(\"X1\"); } }\n", false);
                WriteTemp(Path.Combine(project, "obj", "Debug", "Emitted.cs"), "namespace P { class Emitted { } }\n", false);
                WriteTemp(Path.Combine(dir, "src", "Shared", "Linked.cs"), Spdx + "\nnamespace P { class Linked { } }\n", true);
                WriteTemp(Path.Combine(dir, "leg.json"), "{\"stryker-config\":{\"project\":\"Proj.csproj\",\"mutate\":[\"**/Core/InScope.cs\"]}}", false);
                WriteTemp(Path.Combine(dir, "vacuous.json"),
                    "{\"stryker-config\":{\"project\":\"Proj.csproj\",\"mutate\":[\"**/Core/InScope.cs\",\"**/Gone.cs\"]}}", false);
                WriteTemp(Path.Combine(dir, "everything.json"), "{\"stryker-config\":{\"project\":\"Proj.csproj\"}}", false);

                WriteTemp(Path.Combine(dir, "battery.ps1"),
                    PwshBattery.ScriptPrelude +
                    """
                    function Marked { @(Get-ChildItem -LiteralPath $WorkDir -Recurse -File -Filter '*.cs' | Where-Object { (Get-Content -Raw $_.FullName).Contains('<auto-generated/>') }).Count }
                    function Digest { (Get-ChildItem -LiteralPath $WorkDir -Recurse -File -Filter '*.cs' | Sort-Object FullName | ForEach-Object { (Get-FileHash $_.FullName).Hash }) -join ',' }
                    $original = Digest
                    Show 'working-tree' { $env:GITHUB_ACTIONS = $null; Set-UnmutatedSourcesGenerated -ConfigFile 'leg.json' -Root $WorkDir }
                    Show 'vacuous'      { Set-UnmutatedSourcesGenerated -ConfigFile 'vacuous.json' -Root $WorkDir -Disposable }
                    Show 'untouched'    { if ((Digest) -eq $original) { 'same' } else { 'changed' } }
                    Show 'everything'   { Set-UnmutatedSourcesGenerated -ConfigFile 'everything.json' -Root $WorkDir -Disposable }
                    Show 'marks'        { Set-UnmutatedSourcesGenerated -ConfigFile 'leg.json' -Root $WorkDir -Disposable }
                    Show 'marked-files' { Marked }
                    $afterFirst = Digest
                    Show 'again'        { Set-UnmutatedSourcesGenerated -ConfigFile 'leg.json' -Root $WorkDir -Disposable }
                    Show 'idempotent'   { if ((Digest) -eq $afterFirst) { 'same' } else { 'changed' } }
                    """, false);

                var cases = PwshBattery.Run(dir, 8, "Set-UnmutatedSourcesGenerated");

                Assert.StartsWith("THREW", cases["working-tree"], StringComparison.Ordinal);
                Assert.Contains("never in a working tree", cases["working-tree"], StringComparison.Ordinal);

                // A glob naming nothing refuses the leg, and refuses it before a single source is written.
                Assert.StartsWith("THREW", cases["vacuous"], StringComparison.Ordinal);
                Assert.Contains("**/Gone.cs name no source of Proj.csproj", cases["vacuous"], StringComparison.Ordinal);
                Assert.Equal("OK same", cases["untouched"]);

                // No globs: Stryker mutates everything, so nothing may be marked.
                Assert.Equal("OK 0", cases["everything"]);

                // OutOfScope.cs, NoHeader.cs and the linked Linked.cs; never InScope.cs (named), Descriptors.cs (the
                // release-tracking analyzer reads it) or anything under obj/.
                Assert.Equal("OK 3", cases["marks"]);
                Assert.Equal("OK 3", cases["marked-files"]);
                Assert.Equal("OK 0", cases["again"]);
                Assert.Equal("OK same", cases["idempotent"]);

                Assert.Equal(Spdx + "\nnamespace P { class InScope { } }\n", File.ReadAllText(Path.Combine(project, "Core", "InScope.cs")));
                Assert.DoesNotContain("<auto-generated", File.ReadAllText(Path.Combine(project, "Diagnostics", "Descriptors.cs")), StringComparison.Ordinal);
                Assert.DoesNotContain("<auto-generated", File.ReadAllText(Path.Combine(project, "obj", "Debug", "Emitted.cs")), StringComparison.Ordinal);

                // After the leading comment line, in the file's own line endings; first when there is none.
                Assert.Equal(Spdx + "\r\n" + Marker + "\r\n#nullable enable\r\nnamespace P { class OutOfScope { } }\r\n",
                    File.ReadAllText(Path.Combine(project, "Core", "OutOfScope.cs")));
                Assert.Equal(Marker + "\n#nullable enable\nnamespace P { class NoHeader { } }\n",
                    File.ReadAllText(Path.Combine(project, "Core", "NoHeader.cs")));

                // A byte-order mark survives.
                var linked = File.ReadAllBytes(Path.Combine(dir, "src", "Shared", "Linked.cs"));
                Assert.Equal(new byte[] { 0xEF, 0xBB, 0xBF }, linked[..3]);
                Assert.Equal(Spdx + "\n" + Marker + "\n#nullable enable\nnamespace P { class Linked { } }\n", Encoding.UTF8.GetString(linked, 3, linked.Length - 3));
            }
            finally
            {
                Directory.Delete(dir, true);
            }
        }

        private static void WriteTemp(string path, string text, bool byteOrderMark)
        {
            var parent = Path.GetDirectoryName(path);
            if (parent is not null)
            {
                Directory.CreateDirectory(parent);
            }

            File.WriteAllText(path, text, new UTF8Encoding(byteOrderMark));
        }
    }
}
